# POST /api/sheets/{sheetId}/periods/generate-fy — make the twelve monthly periods of a fiscal year (body:
# {year, user}). Fiscal year FY<year> starts on the first day of the sheet's fiscal start month in that
# calendar year; its months are made exactly as periods/generate makes them (a month whose name is taken or
# whose days overlap a period is left out, each made recorded as PERIOD_ADDED). Answers {generated}. A year
# that is not four digits is refused (400) and nothing is stored.
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGenerated
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods/generate — make one period per calendar month (body: {from, to,
# user}; dates yyyy-MM-dd, a blank one the sheet's today), from the from-date's month to the
# to-date's month, each running from the first to the last day of its month and named yyyy-mm. A
# month whose name is already a period on the sheet (ignoring case), or whose days overlap a period
# on the sheet, is left out and the others are still made; each made is recorded as PERIOD_ADDED.
# Answers {generated}. A bad date or a to before the from is refused (400) and nothing is stored.
validate:
  class: net.officefloor.hq.app.period.ValidateGenerate
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGenerated
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods — add a period (body: {name, from, to, user, cap}; dates yyyy-MM-dd,
# inclusive; cap the most OPEN or PENDING claims a person may have in it, a whole number of at least 1, blank
# for none — anything else is refused; PERIOD_ADDED ends with cap=<n> when given). An empty name, a name another period on the sheet has (ignoring case and the spaces
# around it), a missing or bad date, a to before the from, or dates overlapping another period's is
# refused (400) and nothing is stored. A stored period is recorded in the audit file as PERIOD_ADDED;
# a refused one records nothing.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: check
check:
  class: net.officefloor.hq.app.period.CheckPeriodFree
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.period.SavePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]
=== ValidateGenerateFiscalYear
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Turns a fiscal year into the range of its twelve months: from the sheet's fiscal start month in the year. */
public class ValidateGenerateFiscalYear {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFiscalYearRequest request,
            SettingStore settings, Out<GenerateInput> body, RoleStore roles) throws InvalidSheetException {
        String sheet = sheetId.trim();
        roles.refuseChange(sheet, request == null ? null : request.user());
        String year = request == null || request.year() == null ? "" : request.year().trim();
        if (!year.matches("\\d{4}")) {
            throw new InvalidSheetException("The fiscal year must be a year (YYYY)");
        }
        YearMonth from = YearMonth.of(Integer.parseInt(year), settings.fiscalStartMonth(sheet));
        body.set(new GenerateInput(from, from.plusMonths(11), request.user()));
    }
}
